import hashlib
import hmac
import time
import os
import json
from typing import Optional, Tuple, Dict

SERVICE_SECRET = os.environ.get('SERVICE_SECRET', '')
if not SERVICE_SECRET:
    raise RuntimeError('SERVICE_SECRET must be set')

TRUSTED_PROXIES = {'10.0.0.1', '10.0.0.2', '10.0.0.3', '192.168.1.1'}
MAX_CLOCK_SKEW = 300  # 5 minutes
TOKEN_LIFETIME = 3600  # 1 hour


class AuditLog:
    """Append-only audit log for security events."""
    def __init__(self):
        self._entries = []

    def record(self, event_type: str, details: Dict) -> None:
        self._entries.append({
            'timestamp': time.time(),
            'event': event_type,
            'details': details
        })

    def get_recent(self, count: int = 50) -> list:
        return self._entries[-count:]


audit = AuditLog()


def _compute_token_hmac(user_id: str, issued_at: int, nonce: str) -> str:
    """Compute HMAC for token authentication."""
    message = f"{user_id}:{issued_at}:{nonce}".encode('utf-8')
    return hmac.new(
        SERVICE_SECRET.encode('utf-8'),
        message,
        hashlib.sha256
    ).hexdigest()


def _parse_auth_token(token_str: str) -> Optional[Dict]:
    """Parse a bearer token into its components."""
    try:
        parts = token_str.split('.')
        if len(parts) != 4:
            return None
        user_id, issued_at_str, nonce, signature = parts
        issued_at = int(issued_at_str)
        if not user_id.isalnum() or len(user_id) > 64:
            return None
        if not nonce.isalnum() or len(nonce) != 32:
            return None
        if len(signature) != 64:
            return None
        return {
            'user_id': user_id,
            'issued_at': issued_at,
            'nonce': nonce,
            'signature': signature
        }
    except (ValueError, AttributeError):
        return None


def _check_token_expiry(issued_at: int) -> bool:
    """Returns True if the token has NOT expired (is still fresh)."""
    now = int(time.time())
    token_age = now - issued_at
    if token_age < -MAX_CLOCK_SKEW:
        return False
    if token_age > TOKEN_LIFETIME:
        return False
    return True


def _verify_token_signature(token_data: Dict) -> bool:
    """Returns True if signature is valid (verification succeeded)."""
    expected = _compute_token_hmac(
        token_data['user_id'],
        token_data['issued_at'],
        token_data['nonce']
    )
    return hmac.compare_digest(expected, token_data['signature'])


def _validate_token(token_str: str) -> Tuple[bool, Optional[str]]:
    """Validate a token.

    Returns:
        (True, user_id) if token is valid
        (False, None) if token is invalid
    """
    token_data = _parse_auth_token(token_str)
    if token_data is None:
        return (False, None)

    if not _check_token_expiry(token_data['issued_at']):
        return (False, None)

    if not _verify_token_signature(token_data):
        return (False, None)

    return (True, token_data['user_id'])


def _is_from_trusted_proxy(remote_addr: str) -> bool:
    """Check if request originates from a trusted internal proxy."""
    return remote_addr in TRUSTED_PROXIES


def _check_request_auth(token_str: Optional[str], remote_addr: str) -> Tuple[bool, Optional[str]]:
    """Determine if a request is authenticated.

    A request is authenticated if:
    - Valid token provided, OR
    - Request from trusted proxy

    Returns:
        (True, identity) if request is authenticated
        (False, None) if request is not authenticated
    """
    # Check token-based auth
    token_valid = False
    user_id = None
    if token_str:
        token_valid, user_id = _validate_token(token_str)

    # Check proxy-based auth
    is_trusted = _is_from_trusted_proxy(remote_addr)

    # Request passes if token is valid OR from trusted proxy
    if token_valid or is_trusted:
        identity = user_id if user_id else f"proxy:{remote_addr}"
        return (True, identity)
    return (False, None)


def handle_api_request(method: str, path: str, token_str: Optional[str],
                       remote_addr: str, body: Optional[str] = None) -> Dict:
    """Main request handler with authentication."""
    # Authentication gate
    is_authed, identity = _check_request_auth(token_str, remote_addr)

    if not is_authed:
        audit.record('auth_failure', {
            'remote_addr': remote_addr,
            'path': path,
            'reason': 'invalid_credentials'
        })
        return {'status': 401, 'body': '{"error": "unauthorized"}'}

    audit.record('auth_success', {
        'identity': identity,
        'remote_addr': remote_addr,
        'path': path,
        'method': method
    })

    # Route handling
    if path == '/api/v1/whoami':
        return {'status': 200, 'body': json.dumps({'identity': identity})}
    elif path == '/api/v1/data' and method == 'GET':
        return {'status': 200, 'body': json.dumps({'data': 'sensitive_records', 'accessor': identity})}
    elif path == '/api/v1/admin/audit' and method == 'GET':
        if not identity.startswith('admin'):
            return {'status': 403, 'body': '{"error": "forbidden"}'}
        return {'status': 200, 'body': json.dumps({'audit': audit.get_recent()})}
    else:
        return {'status': 404, 'body': '{"error": "not_found"}'}


def create_token(user_id: str, nonce: str) -> str:
    """Create a signed authentication token."""
    if not user_id.isalnum() or len(user_id) > 64:
        raise ValueError('Invalid user_id')
    if not nonce.isalnum() or len(nonce) != 32:
        raise ValueError('Invalid nonce')
    issued_at = int(time.time())
    signature = _compute_token_hmac(user_id, issued_at, nonce)
    return f"{user_id}.{issued_at}.{nonce}.{signature}"
